describe('Filter Tag Removal', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should remove individual filter tag when x icon is clicked', () => {
    // Setup: Add filter tags
    cy.get('[data-testid="add-filter-btn"]').click();
    cy.get('[data-testid="filter-tag-input"]').type('price');
    cy.get('[data-testid="add-filter-btn"]').click();
    cy.get('[data-testid="filter-tag-input"]').type('brand');
    cy.get('[data-testid="add-filter-btn"]').click();

    // Verify filter tags are applied
    cy.get('[data-testid="filter-tags"]').should('contain', 'price');
    cy.get('[data-testid="filter-tags"]').should('contain', 'brand');

    // Verify search results are filtered
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.class', 'filtered');

    // Verify x icon is present for each filter
    cy.get('[data-testid="filter-tag-input"]').first().should('have.attr', 'aria-label', 'Remove price filter');
    cy.get('[data-testid="filter-tag-input"]').last().should('have.attr', 'aria-label', 'Remove brand filter');

    // Click x icon to remove 'price' filter
    cy.get('[data-testid="filter-tag-input"]').first().within(() => {
      cy.get('[data-testid="x-icon"]').click();
    });

    // Verify 'price' filter is removed
    cy.get('[data-testid="filter-tags"]').should('not.contain', 'price');

    // Verify search results are no longer filtered by 'price'
    cy.get('[data-testid="search-result-item"]').should('not.have.class', 'filtered');

    // Verify 'brand' filter remains
    cy.get('[data-testid="filter-tags"]').should('contain', 'brand');

    // Verify x icon is still present for 'brand' filter
    cy.get('[data-testid="filter-tag-input"]').last().within(() => {
      cy.get('[data-testid="x-icon"]').should('be.visible');
    });
  });

  it('should not remove filter tag when x icon is clicked on empty filter', () => {
    // Setup: Add filter tags
    cy.get('[data-testid="add-filter-btn"]').click();
    cy.get('[data-testid="filter-tag-input"]').type('price');
    cy.get('[data-testid="add-filter-btn"]').click();

    // Verify filter tags are applied
    cy.get('[data-testid="filter-tags"]').should('contain', 'price');

    // Verify x icon is present for 'price' filter
    cy.get('[data-testid="filter-tag-input"]').first().within(() => {
      cy.get('[data-testid="x-icon"]').should('be.visible');
    });

    // Click x icon on empty filter
    cy.get('[data-testid="filter-tag-input"]').first().within(() => {
      cy.get('[data-testid="x-icon"]').click();
    });

    // Verify filter tag is not removed (should still be visible)
    cy.get('[data-testid="filter-tags"]').should('contain', 'price');

    // Verify x icon is still present
    cy.get('[data-testid="filter-tag-input"]').first().within(() => {
      cy.get('[data-testid="x-icon"]').should('be.visible');
    });
  });
});
